    if ([value isKindOfClass:[DMObject class]]) return rosetta_class_name(((DMObject*)value)->_rosettaHandle->cls);
    if ([value isKindOfClass:[DMFunction class]]) return @"a function";
    if ([value isKindOfClass:[DMComplex class]]) return @"a complex number";
