    return v;
}
static uint64_t rosetta_get_u64(rosetta_reader* r) {
    uint64_t v;
    memcpy(&v, rosetta_take(r, 8), 8);
    return v;
}
static double rosetta_get_f64(rosetta_reader* r) {
    double v;
    memcpy(&v, rosetta_take(r, 8), 8);
    return v;
}
static size_t rosetta_get_count(rosetta_reader* r) {
