// The messages C++ sends for the virtual methods of Objective-C subclasses.
static id rosetta_dispatch(DMObject* object, uint32_t generic, NSArray* arguments) {
    if (generic == 14 && arguments.count == 2 && [object isKindOfClass:[DMRbfGaussianProcessSurrogate class]]) {
        DMRbfGaussianProcessSurrogate* target = (DMRbfGaussianProcessSurrogate*)object;
        [target fit:rosetta_convert(arguments[0], "[[d") values:rosetta_convert(arguments[1], "[d")];
        return nil;
    }
    if (generic == 15 && arguments.count == 2 && [object isKindOfClass:[DMRbfGaussianProcessSurrogate class]]) {
        DMRbfGaussianProcessSurrogate* target = (DMRbfGaussianProcessSurrogate*)object;
